import axios from 'axios';

const http = axios.create({ baseURL: process.env.WEATHER_API_URL, timeout: 3000 });

export async function currentConditions(city) {
  const { data } = await http.get('/current', { params: { city } });
  return { tempC: data.temp_c, summary: data.summary };
}

export async function forecast(city, days = 3) {
  const { data } = await http.get('/forecast', { params: { city, days } });
  return data.days;
}
